import { HttpClient, HttpParams } from '@angular/common/http';

getPage(page: number, limit = 10) {
  const params = new HttpParams()
    .set('_page', page)
    .set('_limit', limit);

  return this.http.get<User[]>('http://localhost:3000/users', {
    params,
    observe: 'response'   // give me headers too
  });
}

